// НЕ ПРОВЕРЕН В ЖИВОМ БРАУЗЕРЕ: подмена user_profiles через page.route была недоступна при генерации; написан строго по плану.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { startNearestPrayer } from '../_helpers/prayer-start';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

function setLegacyNusach(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(setLegacyNusach);
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = { ...(value as Record<string, unknown>) };
    if ('nusach' in out) out.nusach = 'ספרד / עדות המזרח';
    return out;
  }
  return value;
}

test.describe('Смена нусаха внутри молитвы', () => {
  test('NS-03 Старое значение профиля «ספרד / עדות המזרח» — везде как ספרד, одна строка о нусахе, заголовок = показанный нусах #ecda5d38 @prod-safe @mobile', async ({ page }) => {
    // 1. До перехода: подменить GET-ответ user_profiles (nusach → «ספרד / עדות המזרח»).
    const pattern = '**/rest/v1/user_profiles*';
    const handler = async (route: import('@playwright/test').Route) => {
      if (route.request().method() !== 'GET') return route.continue();
      const response = await route.fetch();
      let json: unknown;
      try {
        json = await response.json();
      } catch {
        return route.fulfill({ response });
      }
      return route.fulfill({ response, json: setLegacyNusach(json) });
    };
    await page.route(pattern, handler);

    // 2. Открыть `/prayers`.
    await page.goto('/prayers');
    await expect(page.getByText('התפילות מוצגות בנוסח ספרד שנשמר בפרופיל.')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('נוסח התפילה ספרדי').first()).toBeVisible();
    await expect(page.getByText('נוסח התפילה אשכנזי')).toHaveCount(0);
    await expect(page.locator('body')).not.toContainText('אינו זמין');

    // 3. Открыть `/home` → карточка ближайшей молитвы → «התחל תפילה».
    await page.goto('/home');
    await expect(page.getByText('נוסח ספרד').first()).toBeVisible({ timeout: 20_000 });
    // Вне окна молитвы кнопка неактивна (норма): хелпер проверяет disabled + «מתחילה ב-…» и открывает
    // /prayer/<תפילה>_<נוסח из карточки> (подмена профиля продолжает действовать).
    await startNearestPrayer(page);
    await expect(page).toHaveURL(/\/prayer\/[a-z_]+_sfarad$/);
    await expect(page.getByRole('heading', { level: 1 })).toContainText('(ספרדי)');
    await expect(page.locator('body')).not.toContainText('עדות המזרח');
    await expect(page.locator('body')).not.toContainText('אשכנז');

    // 4. Снять подмену.
    await page.unroute(pattern, handler);
  });
});
